  /** The UUIDs of labels removed by this entry. The corresponding label records may no longer be available if they were deleted. */
  removedLabelIds?: Array<string> | null
  /** UUIDs of releases the issue was added to. */
  addedToReleaseIds?: Array<string> | null
  /** UUIDs of releases the issue was removed from. */
  removedFromReleaseIds?: Array<string> | null
  /** Changed issue relationships. */
  relationChanges?: Array<IssueRelationHistoryPayload> | null
  /** Whether the issue was auto-closed. */
  autoClosed?: boolean | null
  /** Whether the issue was auto-archived. */
  autoArchived?: boolean | null
  /** The due date before this change, as YYYY-MM-DD without a time or time zone. Null if there was no due date or this entry does not record a due-date change. */
